/* @autogenerated */
import { RoleRepository } from 'app/features/access/role/repository/role-repository.service';
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { Role } from 'app/features/access/role/model/role.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de role: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'role-view-bulk-edit-action', standalone: false, template: '' })
export class RoleViewBulkEditActionComponent extends BaseBulkEditAction<Role> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'access/role';
  protected readonly repository = inject(RoleRepository);

  protected override keyOf(item: Role): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<Role>[] {
    return [
      { name: 'name', label: this.text('fieldName'), type: 'text' },
      { name: 'resourceServer', label: this.text('fieldResourceServer'), type: 'relation', optional: true },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<Role> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
